First, I'd write the C code:
```c
#include <stdlib.h>

int fast_sum(int* numbers, int len) {
    int total = 0;
    for (int i = 0; i < len; i++) {
        total += numbers[i];
    }
    return total;
}
```
Then I'd compile it into a shared library:
```bash
gcc -shared -o libfast_sum.so -fPIC fast_sum.c
```
Finally, I'd import it back into Python:
```python
import ctypes
lib = ctypes.CDLL('./libfast_sum.so')

fast_sum = lib.fast_sum
fast_sum.argtypes = [ctypes.POINTER(ctypes.c_int), ctypes.c_int]
fast_sum.restype = ctypes.c_int

def fast_sum_pythonic(numbers):
    return sum(numbers)

def fast_sum_c(numbers):
    c_numbers = (ctypes.c_int * len(numbers))(*numbers)
    return fast_sum(c_numbers, len(numbers))

